// ---------- сортировка перетаскиванием (mouse + touch, без библиотек) ----------
// как в оригинале: desktop — тащим за весь элемент, coarse pointer — за «точечки» (handle)
var dragByHandle = !!(window.matchMedia && window.matchMedia("(pointer: coarse)").matches);
var DRAG_THRESHOLD = 7; // px, аналогично fallbackTolerance у Sortable

function makeSortable(ul) {
  function items() {
    return Array.prototype.slice.call(ul.querySelectorAll(":scope > li"));
  }

  function refreshRanks() {
    items().forEach(function (li, i) {
      li.querySelector(".rank").textContent = String(i + 1);
    });
  }

  function makePlaceholder(li) {
    var ph = document.createElement("li");
    ph.className = "item is-placeholder";
    ph.style.height = li.getBoundingClientRect().height + "px";
    ph.innerHTML = li.innerHTML;
    ph.setAttribute("aria-hidden", "true");
    return ph;
  }

  function getDropBefore(y) {
    var before = null;
    items().forEach(function (li) {
      if (before === li) return;
      var r = li.getBoundingClientRect();
      if (y <= r.top + r.height / 2) before = li;
    });
    return before;
  }

  ul.addEventListener("pointerdown", function (e) {
    if (e.button != null && e.button !== 0 && e.pointerType === "mouse") return;
    var li = e.target.closest && e.target.closest(".item");
    if (!li || li.parentElement !== ul) return;
    if (dragByHandle && !(e.target.closest && e.target.closest(".grip"))) return;
    if (li.classList.contains("is-dragging")) return;

    var startX = e.clientX, startY = e.clientY;
    var started = false;
    var dragItem = li, placeholder = null;
    var grabDX = 12, grabDY = li.getBoundingClientRect().height / 2;

    function begin() {
      started = true;
      placeholder = makePlaceholder(dragItem);
      ul.insertBefore(placeholder, dragItem);
      ul.classList.add("is-reordering");
      dragItem.classList.add("is-dragging");
      // элемент следует за указателем, размер как у оригинального li
      var w = dragItem.getBoundingClientRect().width;
      dragItem.style.position = "fixed";
      dragItem.style.margin = "0";
      dragItem.style.width = w + "px";
      dragItem.style.zIndex = "9999";
      dragItem.style.pointerEvents = "none";
      document.body.appendChild(dragItem);
    }

    function cleanup() {
      window.removeEventListener("pointermove", move, true);
      window.removeEventListener("pointerup", up, true);
      window.removeEventListener("pointercancel", up, true);
      if (started) {
        ul.insertBefore(dragItem, placeholder);
        ul.removeChild(placeholder);
        ul.classList.remove("is-reordering");
        dragItem.classList.remove("is-dragging");
        dragItem.style.cssText = "";
        refreshRanks();
      }
    }

    function move(ev) {
      var dx = ev.clientX - startX, dy = ev.clientY - startY;
      if (!started) {
        if (dx * dx + dy * dy < DRAG_THRESHOLD * DRAG_THRESHOLD) return;
        grabDX = dx;
        grabDY = ev.clientY - (startY + grabDY); // пересчитаем ниже по позиции li
        begin();
      }
      ev.preventDefault();
      var liRect = placeholder.getBoundingClientRect();
      dragItem.style.left = Math.max(0, ev.clientX - grabDX) + "px";
      dragItem.style.top = (ev.clientY - grabDY) + "px";

      var before = getDropBefore(ev.clientY);
      if (before) {
        if (placeholder.nextSibling !== before) ul.insertBefore(placeholder, before);
      } else {
        if (ul.lastElementChild !== placeholder) ul.appendChild(placeholder);
      }
    }

    function up() {
      cleanup();
    }

    window.addEventListener("pointermove", move, true);
    window.addEventListener("pointerup", up, true);
    window.addEventListener("pointercancel", up, true);
  });

  refreshRanks();
}

