        placeholder.className = "item is-placeholder";
        var phRank = el("span", "rank");
        phRank.setAttribute("aria-hidden", "true");
        phRank.style.visibility = "hidden";
        var phLabel = document.createElement("span");
        phLabel.className = "label";
        phLabel.style.visibility = "hidden";
        phLabel.textContent = "•";
        var phGrip = document.createElement("span");
        phGrip.className = "grip";
        phGrip.innerHTML = GRIP_SVG;
        placeholder.appendChild(phRank);
        placeholder.appendChild(phLabel);
        placeholder.appendChild(phGrip);
        placeholder.style.height = liRect.height + "px";
        ul.insertBefore(placeholder, li2);
        ul.classList.add("is-reordering");
        li2.classList.add("is-dragging");
        li2.style.left = "";
        li2.style.top = "";
        li2.style.margin = "0";
        li2.style.width = liRect.width + "px";
        li2.style.position = "fixed";
        li2.style.zIndex = "9999";
        li2.style.pointerEvents = "none";
        document.body.appendChild(li2);
      }
      var ev2 = ev;
      var offsetX = ev2.clientX - ((dragItem._ox != null ? dragItem._ox : 8));
      dragItem.style.left = (ev2.clientX - 8) + "px";
      dragItem.style.top = (ev2.clientY - 16) + "px";

      // пересчёт позиции placeholder (для мобильных — страница не должна скроллиться впринципе)
      ev.preventDefault();
      var after = getAfterItem(ev2.clientY);
      if (after) {
        if (placeholder.nextSibling === after) return;
        ul.insertBefore(placeholder, after);
      } else {
        if (placeholder === ul.lastElementChild && after === null && ul.lastElementChild === placeholder) return;
        ul.appendChild(placeholder);
      }
    };

    function up() {
      window.removeEventListener("pointermove", move, true);
      window.removeEventListener("pointerup", up, true);
      window.removeEventListener("pointercancel", up, true);
      if (dragItem && placeholder) {
        if (started) {
          ul.insertBefore(dragItem, placeholder);
          ul.removeChild(placeholder);
        }
        ul.classList.remove("is-reordering");
        dragItem.classList.remove("is-dragging");
        dragItem.style.cssText = "";
        dragItem.draggable = true;
        refreshRanks();
      }
      dragItem = null;
      placeholder = null;
    }

    window.addEventListener("pointermove", move, true);
    window.addEventListener("pointerup", up, true);
    window.addEventListener("pointercancel", up, true);
  }

  ul.addEventListener("pointerdown", onPointerDown);
  refreshRanks();
}

